static inline int32_t tri_q(uint32_t ph) /* a triangle -2048..2047 (so Q8 = +-8 samples) */
{
    int32_t t = (int32_t)(ph >> 19); /* 0..8191 */
    return t < 4096 ? t - 2048 : 6143 - t;
}
