/* a sound's ensemble: its line, its two LFOs, the brigade's filters, the depth as it glides */
typedef struct {
    line_t l;
    uint32_t ph_s, ph_f, inc_s, inc_f, mode, active;
    int32_t depth_s, depth_f, mix, lp, lp2, lpl, lpl2, lpr, lpr2, cur_s, cur_f;
    int32_t w[3], dw[3]; /* the three lines' delays now (Q16) and their step a sample in this block */
    uint32_t wok; /* w holds a value */
} ens_t;
static void ens_taps(const ens_t *e, int32_t *w) /* the three delays at the LFOs' phases now (Q16 samples) */
{
    w[0] = (265 << 16) + sin_q15(e->ph_s) * e->cur_s + sin_q15(e->ph_f) * e->cur_f;
    w[1] = (265 << 16) + sin_q15(e->ph_s + 0x55555555u) * e->cur_s + sin_q15(e->ph_f + 0x55555555u) * e->cur_f;
    w[2] = (265 << 16) + sin_q15(e->ph_s + 0xAAAAAAAAu) * e->cur_s + sin_q15(e->ph_f + 0xAAAAAAAAu) * e->cur_f;
}
