    line_init(&PKV(2), 32768u);
    line_init(&PKV(3), 32768u);
    line_init(&PKV(4), (8192u / 1u));
    line_init(&PKV(5)[0], ((uint32_t)((142) * 44100u / 29761u / 1u))); line_init(&PKV(5)[1], ((uint32_t)((107) * 44100u / 29761u / 1u))); line_init(&PKV(5)[2], ((uint32_t)((379) * 44100u / 29761u / 1u))); line_init(&PKV(5)[3], ((uint32_t)((277) * 44100u / 29761u / 1u)));
    line_init(&PKV(6), ((uint32_t)((672) * 44100u / 29761u / 1u)) + 16u); line_init(&PKV(7), ((uint32_t)((4453) * 44100u / 29761u / 1u))); line_init(&PKV(8), ((uint32_t)((1800) * 44100u / 29761u / 1u))); line_init(&PKV(9), ((uint32_t)((3720) * 44100u / 29761u / 1u)));
    line_init(&PKV(10), ((uint32_t)((908) * 44100u / 29761u / 1u)) + 16u); line_init(&PKV(11), ((uint32_t)((4217) * 44100u / 29761u / 1u))); line_init(&PKV(12), ((uint32_t)((2656) * 44100u / 29761u / 1u))); line_init(&PKV(13), ((uint32_t)((3163) * 44100u / 29761u / 1u)));
    PKV(25) = PKV(24) = 11025 << 16;
