    d = p->v[P_REV_SIZE]; PKV(20) = 12000 + ((d * d * 19500) >> 14); /* 0.37 .. 0.96: the top is a near-freeze */
    d = p->v[P_REV_DAMP]; PKV(21) = 32768 - d * d * 2; /* the one-pole's k at the half rate */
