    PKV(14) += 97391u * 1u; /* ~1.0 Hz and ~0.7 Hz: the tank's sway against metallic rings */
    PKV(15) += 68174u * 1u;
    line_write(&PKV(4), in);
    x = line_read(&PKV(4), PKV(33));
    PKV(28) += ((x - PKV(28)) * (1u == 2u ? 24000 : 16700)) >> 15;
    x = ap_step(&PKV(5)[0], PKV(28), 24576);
