    a = x + ((line_read(&PKV(9), ((uint32_t)((3720) * 44100u / 29761u / 1u))) * dec) >> 15);
    a = ap_mod(&PKV(10), a, -22938, ((uint32_t)((908) * 44100u / 29761u / 1u)), e2);
    line_write(&PKV(11), a);
