    uint32_t i, v, pick = 0, best = 0xFFFFFFFFu, n = 0;
    for (v = 0; v < 16u; v++) n += PKV(64)[v].ae.stage != E_IDLE;
    for (i = 0; i < 16u && n < PKV(101); i++) { /* (at the guard's limit: steal, as if all were busy) */
        v = (PKV(66) + i) % 16u;
        if (PKV(64)[v].ae.stage == E_IDLE) { PKV(66) = v + 1u; return v; }
    }
    for (v = 0; v < 16u; v++)
        if (!PKV(64)[v].gate && PKV(64)[v].seq < best) { best = PKV(64)[v].seq; pick = v; }
    if (best == 0xFFFFFFFFu)
        for (v = 0; v < 16u; v++)
            if (PKV(64)[v].seq < best) { best = PKV(64)[v].seq; pick = v; }
    if (n >= PKV(101) && PKV(64)[pick].ae.stage == E_IDLE) /* (stealing at the limit: a sounding one, not a quiet card) */
        for (v = 0, best = 0xFFFFFFFFu; v < 16u; v++)
            if (PKV(64)[v].ae.stage != E_IDLE && PKV(64)[v].seq < best) { best = PKV(64)[v].seq; pick = v; }
