    g->w_lo = (pv[P_CBASS] ? 1u : 0u) | (pv[P_CELLO] ? 2u : 0u);
    g->w_up = (pv[P_VIOLA] ? 4u : 0u) | (pv[P_VIOLIN] ? 8u : 0u) | (pv[P_TRUMPET] || pv[P_HORN] ? 16u : 0u);
