/* ---- a fresh pattern */
static void step_clear(step_t *s)
{
    uint32_t i;
    for (i = 0; i < 4u; i++) s->note[i] = 0;
    s->vel = 100;
    s->gate = 96; /* 76 % */
    s->ratch = 0;
    s->chance = 100;
    s->nudge = 0;
}
static void lane_clear(lane_t *l) { uint32_t i; l->param = 0xFFu; for (i = 0; i < 256u; i++) l->v[i] = 0xFFu; }
static void auto_init(pattern_t *p)
{
    uint32_t t, l;
    p->auto_magic = 0x4F545541u;
    for (t = 0; t < 4u; t++) for (l = 0; l < 4u; l++) lane_clear(&p->lane[t][l]);
}
static void pat_init(pattern_t *p)
{
    uint32_t i, t;
    p->magic = 0x34514553u;
    auto_init(p);
    for (t = 0; t < 4u; t++) {
        for (i = 0; i < 256u; i++) step_clear(&p->st[t][i]);
        p->trk[t].len = 16; /* a bar of sixteenths each */
        p->trk[t].div = D_16;
        p->trk[t].swing = 50;
        p->trk[t].transp = 0;
        p->trk[t].mute = 0;
        p->trk[t].pad[0] = p->trk[t].pad[1] = 0;
    }
}
static void pat_factory(uint32_t n, pattern_t *p) /* a pattern never saved: empty, four bars of sixteenths */
{
    (void)n;
    pat_init(p);
}
/* ---- the player (ISR, per CTL block) */
