static void sg_itoa(int32_t v, char *o)
{
    char t[12]; int n = 0, neg = v < 0; uint32_t u = neg ? (uint32_t)(-v) : (uint32_t)v;
    do { t[n++] = (char)('0' + u % 10u); u /= 10u; } while (u);
    if (neg) *o++ = '-';
    while (n) *o++ = t[--n];
    *o = 0;
}
static void sg_scpy(char *o, const char *s) { uint32_t i = 0; while (s && s[i] && i < 23u) { o[i] = s[i]; i++; } o[i] = 0; }
static void sg_init(void)
{
    uint32_t p;
    for (p = 0; p < 4u; p++) patch_defaults(&PKV(54)[p]);
    engine_init();
}
static const char *sg_eng_name(uint32_t e) { (void)e; return "SHINE ON"; }
static uint32_t sg_num_sounds(uint32_t e) { (void)e; return 32u; }
static const char *sg_sound_name(uint32_t e, uint32_t s) { (void)e; return FACTORY[s].name; }
static uint32_t sg_num_params(uint32_t e) { (void)e; return (sizeof SG_E / sizeof SG_E[0]); }
static void sg_param(uint32_t e, uint32_t k, const char **label, int32_t *min, int32_t *max, int32_t *def)
{
    (void)e;
    *label = SG_E[k].label; *min = 0; *max = PDEF[SG_E[k].p].max; *def = PDEF[SG_E[k].p].def;
}
static void sg_format(uint32_t e, uint32_t k, int32_t v, char *out)
{
    static const char *const WAVE[] = {"OFF", "SAW", "PLS", "S+P"};
    static const char *const LSH[] = {"TRI", "SAW", "RAMP", "SQR", "S&H", "RND"};
    uint32_t kind = PDEF[SG_E[k].p].kind;
    (void)e;
    (void)WAVE; (void)LSH;
    if (kind == K_ONOFF) sg_scpy(out, v ? "ON" : "OFF");
    else if (kind == K_ENS && v >= 0 && v < 4) { static const char *const EN[] = {"OFF", "MONO", "STEREO", "WIDE"}; sg_scpy(out, EN[v]); }
    else if (kind == K_OCTS) sg_itoa(v - 1, out);
    else if (kind == K_BIP) sg_itoa(v - 64, out);
    else sg_itoa(v, out);
}
static void sg_sound(uint32_t e, uint32_t s)
{
    (void)e;
    patch_from_factory(&(PKV(54)[0]), &FACTORY[s % (32u)]);
    (PKV(54)[0]).v[P_BEND] = 24; /* the plugin's Bend sets the range */
}
static int32_t sg_gete(uint32_t k) { return (PKV(54)[0]).v[SG_E[k].p]; }
static void sg_sete(uint32_t k, int32_t v)
{
    uint32_t p = SG_E[k].p;
    (PKV(54)[0]).v[p] = (uint8_t)(v < 0 ? 0 : v > PDEF[p].max ? PDEF[p].max : v);
}
static int sg_getc(uint32_t i, int32_t *v)
{
    uint32_t n;
    for (n = 0; n < (sizeof SG_C / sizeof SG_C[0]); n++)
        if (SG_C[n].c == i) {
            int32_t x = (PKV(54)[0]).v[SG_C[n].p];
            if (SG_C[n].mode == 1) x = x / 2;
            else if (SG_C[n].mode == 2) x = 0;
            else if (SG_C[n].mode == 3) x = x * 127 / (int32_t)PDEF[SG_C[n].p].max;
            *v = x;
            return 1;
        }
    return 0;
}
static void sg_setc(uint32_t i, int32_t v)
{
    uint32_t n;
    for (n = 0; n < (sizeof SG_C / sizeof SG_C[0]); n++)
        if (SG_C[n].c == i) {
            uint32_t p = SG_C[n].p;
            int32_t x = v;
            if (SG_C[n].mode == 1) x = (v < 0 ? -v : v) * 2;
            else if (SG_C[n].mode == 2) x = 0;
            else if (SG_C[n].mode == 3) x = (v * (int32_t)PDEF[p].max + 63) / 127;
            (PKV(54)[0]).v[p] = (uint8_t)(x < 0 ? 0 : x > PDEF[p].max ? PDEF[p].max : x);
        }
}
static void sg_tune(int32_t cents) { (void)cents; }
static void sg_note(uint32_t on, uint32_t note, uint32_t vel) { note_event(on, note, vel); }
static void sg_all_off(void) { voices_release_all(); }
static void sg_bend(int32_t cents) { PKV(70) = cents * 8191 / 2400; }
static void sg_mod(int32_t v) { (void)v; }
static void sg_render(int32_t *o, uint32_t n)
{
    uint32_t i;
    for (i = 0; i < 2u * n; i++) o[i] = 0;
    engine_audio(o, n);
}

